for i,identifier in enumerate(['FICTIF100','FICTIF200','FICTIF300'],1):
 source['equipment'].append({'id':'e'+str(i),'siteId':i,'identifier':identifier,'designation':'Matériel fictif '+str(i),'serialNumber':'','sector':'B2','team':'A','zone':'DMCR','owner':'','location':'Lieu fictif','category':'','assignment':'','comments':'','months':12,'controls':[],'archived':False,'archiveHistory':[]})
