 # Incorrect matching can be corrected in the searchable menu.
 rows.nth(1).locator('[data-apave-equipment]').select_option('e3',force=True);page.locator('#apaveConfirmed').check();expect(page.locator('#apaveApply')).to_be_enabled();page.once('dialog',lambda d:d.accept());page.locator('#apaveApply').click();expect(page.locator('#apaveStatus')).to_contain_text('2 constat(s) importé(s)');stored=json.loads(page.evaluate("localStorage.getItem('vgp-prototype-v1')"));assert len(stored['equipment'][0]['controls'])==1;assert stored['equipment'][0]['controls'][0]['result']=='Mauvais état — réparable';assert stored['equipment'][1]['controls']==[];assert stored['equipment'][2]['controls']==[];assert stored['equipment'][2]['apaveChecks'][0]['state']=='not_verified';assert 'base64' not in json.dumps(stored);assert len(stored['apaveReports'])==1
 page.locator('#apaveClose').click();page.locator('[data-open=e1]').click();expect(page.locator('#detail [data-apave-hash]')).to_have_count(1);expect(page.locator('#detailContent')).to_contain_text('Page 1');page.locator('#detail [data-close]').click();page.locator('#apaveImport').click();page.locator('#apaveFile').set_input_files(pdfpath);expect(page.locator('#apaveRows')).to_contain_text('Déjà importé',timeout=30000);assert page.locator('[data-apave-selected]:checked').count()==0;assert not external,external;assert not errors,errors;b.close()
